protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    while (start < end) {
        // Split time ranges to insure the start time and end time is small then  {@link #FETCH_DATA_DURATION}
        long duration = Math.min(end - start, FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(start, start + duration));
        start += duration;
    }

    return timeRanges;
}

List<TimeRange> function(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    while (duration > FETCH_DATA_DURATION) {
        long splitStart = start + (duration - FETCH_DATA_DURATION);
        long splitEnd = end - (FETCH_DATA_DURATION - splitStart);
        timeRanges.add(new TimeRange(start, splitStart));
        timeRanges.add(new TimeRange(splitEnd, end));
        start = splitStart;
        end = splitEnd;
        duration = end - start;
    }
    return timeRanges;
}

