protected List<TimeRange> buildTimeRanges(long start, long end) {

  * Split time ranges to ensure the start time and end time is small than {@link #FETCH_DATA_DURATION}

  * Initialize the list of time ranges
  List<TimeRange> timeRanges = new ArrayList<>();

  * Calculate the number of intervals
  int intervals = (int) ((end - start) / FETCH_DATA_DURATION.toMillis());

  * If the number of intervals is 0, return the list with a single time range
  if (intervals == 0) {
    timeRanges.add(new TimeRange(Instant.ofEpochMilli(start), Instant.ofEpochMilli(end)));
    return timeRanges;
  }

  * Loop through each interval
  for (int i = 0; i < intervals; i++) {
    * Calculate the start and end times for the current interval
    long intervalStart = start + (i * FETCH_DATA_DURATION.toMillis());
    long intervalEnd = intervalStart + FETCH_DATA_DURATION.toMillis();

    * Add the current interval to the list of time ranges
    timeRanges.add(new TimeRange(Instant.ofEpochMilli(intervalStart), Instant.ofEpochMilli(intervalEnd)));
  }

  return timeRanges;
}

