long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep == 0) {
        return timeBucket;
    }
    // calculate the correct day of the week for the given timeBucket
    int dayOfWeek = (int) (timeBucket % 1000000L);
    dayOfWeek = (dayOfWeek - 1) * dayStep;
    while (dayOfWeek < 1000000L) {
        dayOfWeek += dayStep;
    }
    // reformat the time bucket with the adjusted day of the week
    return timeBucket - dayOfWeek;
}

