    if (path.isEmpty()) {
        pathSegments.add(new PathSegmentImpl("", null));
        return pathSegments;
    }

    int start = 0;
    int end = 0;
    if (path.startsWith("/")) {
        start = 1;
    }
    while (end < path.length() - 1) {
        end = path.indexOf('/', start);
        if (end == -1) {
