private void pop(final String descriptor){
    final Stack<AbstractType> stack = getOutputFrame().getStack();
    final List<AbstractType> outputTypes = new ArrayList<>();

    for (int i = 0; i < descriptor.length(); i++) {
        final char c = descriptor.charAt(i);
        if (c == 'Z') {
            outputTypes.add(AbstractType.BOOLEAN);
        } else if (c == 'B') {
            outputTypes.add(AbstractType.BYTE);
        } else if (c == 'C') {
            outputTypes.add(AbstractType.CHARACTER);
        } else if (c == 'S') {
            outputTypes.add(AbstractType.SHORT);
        } else if (c == 'I') {
            outputTypes.add(AbstractType.INTEGER);
        } else if (c == 'F') {
            outputTypes.add(AbstractType.FLOAT);
        } else if (c == 'J') {
            outputTypes.add(AbstractType.LONG);
        } else if (c == 'D') {
            outputTypes.add(AbstractType.DOUBLE);
        } else if (c == 'L') {
            i++;
            final int end = descriptor.indexOf(';', i);
            final String className = descriptor.substring(i, end);
            outputTypes.add(new AbstractType(className));
            i = end;
        }
    }

    for (final AbstractType outputType : outputTypes) {
        final AbstractType stackType = stack.peek();
        if (!stackType.isSameType(outputType)) {
            throw new IllegalArgumentException("Stack type " + stackType + " is not the same as output type " + outputType);
        }
        stack.pop();
    }
}

void write(final byte[] b, final int off, final int len) throws IOException {
    checkBoundary(b, off, len);
    int bytesWritten = 0;
    while (bytesWritten < len) {
        int bytesToWrite = Math.min(len - bytesWritten, BUFFER_SIZE);
        write(b, off + bytesWritten, bytesToWrite);
        bytesWritten += bytesToWrite;
    }
}

public void write(final byte b[], final int off, final int len) throws IOException {
    checkBoundary(b.length, off, len);
    int remaining = len;
    int pos = off;
    while (remaining > 0) {
        int toWrite = Math.min(remaining, 1 << 16);
        writeShort(toWrite);
        writeBytes(b, pos, toWrite);
        remaining -= toWrite;
        pos += toWrite;
    }
}

