    if (in == null) {
        throw new IllegalArgumentException("Cannot read from null stream");
    }

    // Clear the existing buffer
    buffer.clear();

    // Read from the input stream
    int bytesRead = in.read(buffer.array());
    if (bytesRead == -1) {
        throw new EOFException("Reached end of stream before filling buffer");
    }

