void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new NullPointerException("Input stream cannot be null");
    }

    int bytesRead = 0;
    byte[] buffer = new byte[WRITE_CHUNK_SIZE];
    while (bytesRead < in.available()) {
        int read = in.read(buffer, 0, WRITE_CHUNK_SIZE);
        if (read < 0) {
            break;
        }
        bytesRead += read;
        buffer = in.read(buffer, read, WRITE_CHUNK_SIZE - read);
    }

    if (bytesRead > 0) {
        throw new EOFException("Reached end of input stream before filling the entire buffer");
    }
}

