private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Iterator<Node> iterator = start.getNeighbors(dir).iterator();
    while (iterator.hasNext()) {
        Node node = iterator.next();
        if (predicate.test(node)) {
            return OuterFaceCirculator.create(node, iterator);
        }
    }
    return OuterFaceCirculator.create(stop, iterator);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Initialize the circulator with the given parameters
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

    // Iterate over the nodes on the outer face of the current node
    while (circulator.hasNext()) {
        // Get the next node on the outer face
        Node node = circulator.next();

        // Check if the current node satisfies the predicate
        if (predicate.test(node)) {
            // Found a node that satisfies the predicate, return the circulator
            return circulator;
        }
    }

    // No nodes were found that satisfy the predicate, return the original circulator
    return circulator;
}

