public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // parse the file and extract the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    if (!file.exists()) {
        throw new IOException("File not found: " + file.getAbsolutePath());
    }
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // parse the line and extract the thread snapshot information
            String[] parts = line.split(",");
            if (parts.length != 5) {
                throw new IOException("Invalid line format in thread snapshot file: " + line);
            }
            int threadId = Integer.parseInt(parts[0]);
            long timeMillis = Long.parseLong(parts[1]);
            boolean isDaemon = Boolean.parseBoolean(parts[2]);
            String threadName = parts[3];
            int stackTraceId = Integer.parseInt(parts[4]);
            threadSnapshots.add(new ThreadSnapshot(threadId, timeMillis, isDaemon, threadName, stackTraceId));
        }
    } catch (IOException e) {
        throw new IOException("Error parsing thread snapshot file: " + file.getAbsolutePath(), e);
    }
    // filter the thread snapshots based on the time range
    List<ThreadSnapshot> filteredThreadSnapshots = new ArrayList<>();
    for (ThreadSnapshot threadSnapshot : threadSnapshots) {
        boolean matchTimeRange = false;
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (threadSnapshot.getTimeMillis() >= timeRange.getStartTimeMillis() && threadSnapshot.getTimeMillis() <= timeRange.getEndTimeMillis()) {
                matchTimeRange = true;
                break;
            }
        }
        if (matchTimeRange) {
            filteredThreadSnapshots.add(threadSnapshot);
        }
    }
    return filteredThreadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
