public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<ThreadSnapshot>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.isEmpty()) {
                continue;
            }
            // Get the thread name and time from the line
            String[] tokens = line.split(",");
            String threadName = tokens[0];
            long threadId = Long.parseLong(tokens[1]);
            long time = Long.parseLong(tokens[2]);

            // Check if the time is within any of the given time ranges
            boolean isInTimeRange = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (time >= timeRange.getStart() && time <= timeRange.getEnd()) {
                    isInTimeRange = true;
                    break;
                }
            }

            if (!isInTimeRange) {
                continue;
            }

            // Create a new thread snapshot for the current thread
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(threadId, threadName, time);
            threadSnapshots.add(threadSnapshot);
        }
    } catch (IOException e) {
        throw e;
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
