        while ((line = reader.readLine()) != null) {
            String[] columns = line.split(",");
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            threadSnapshot.setThreadName(columns[0]);
            threadSnapshot.setThreadId(Integer.parseInt(columns[1]));
            threadSnapshot.setGroupName(columns[2]);
            threadSnapshot.setParentGroupName(columns[3]);
            threadSnapshot.setStackTrace(StackTrace.fromString(columns[4]));
            String[] timeRange = columns[5].split("-");
            threadSnapshot.setStartTime(Long.parseLong(timeRange[0]));
            threadSnapshot.setEndTime(Long.parseLong(timeRange[1]));
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

